SELECT * FROM customer_shopping_behavior.customer;

#1 what is the total revenue generated by male vs female customers?
 select gender, sum(purchase_amount) as revenue
 from customer_shopping_behavior.customer
 group by gender; 

#2 which customers used a  discount but still spent more than the average purchase amount?
select customer_id, purchase_amount
from customer_shopping_behavior.customer
where discount_applied= 'Yes' and purchase_amount >= (select avg (purchase_amount) from customer_shopping_behavior.customer );

#3 which are the top 5 products with the highest average review rating?
select item_purchased,avg(review_rating) as "Average Product Rating"
from customer_shopping_behavior.customer
group by item_purchased
order by avg (review_rating) desc
limit 5;

#4 compare the average purchase amounts between standard and express shipping?
select shipping_type,
avg(purchase_amount)
from customer_shopping_behavior.customer
where shipping_type in ('Standard', 'Express')
group by shipping_type;

#5 Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non subscribers
select subscription_status,
Count(customer_id) as total_customers,
round(avg(purchase_amount),2) as avg_spend,
round(SUM(purchase_amount),2) as total_revenue
from customer_shopping_behavior.customer
group by subscription_status
order by total_revenue, avg_spend desc;

#6 which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased, 
round(100 * sum(case when discount_applied= 'Yes' then 1 else 0 end)/ count(*),2) as discount_rate
from customer_shopping_behavior.customer
group by item_purchased
order by discount_rate desc
limit 5;

#7 Segment customers into New, Returning and Loyal based in their total number of previous purchases and show the count of each segment
with customer_type as (
select customer_id, previous_purchases,
case
 when previous_purchases = 1 then 'New'
 when previous_purchases between 2 and 10 then 'Returning'
 else 'Loyal'
 end as customer_segment
 from customer_shopping_behavior.customer
 )
 select customer_segment, count(*) as "Number of Customers"
 from customer_type
 group by customer_segment;
 
#8 what are the top 3 most purchased products within each category?
with item_counts as (
select category,
item_purchased,
count(customer_id) as total_orders,
row_number() over (partition by category order by count(customer_id) desc) as item_rank
from customer_shopping_behavior.customer
group by category, item_purchased
)
select item_rank, category, item_purchased, total_orders
from item_counts
where item_rank <= 3;

#9 Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select subscription_status,
count(customer_id) as repeat_buyers
from customer_shopping_behavior.customer
where previous_purchases > 5
group by subscription_status;

#10 what is the revenue contribution of each age group?
select age_group,
sum(purchase_amount) as total_revenue
from customer_shopping_behavior.customer
group by age_group
order by total_revenue desc;

# 11 Which items had at least 160 orders?

SELECT item_purchased, COUNT(*) AS orders
FROM customer_shopping_behavior.customer
GROUP BY item_purchased
HAVING COUNT(*) >= 160
ORDER BY orders DESC;

#12 Revenue and % of total for each category
SELECT category,
       SUM(purchase_amount) AS revenue,
       ROUND(100 * SUM(purchase_amount) / SUM(SUM(purchase_amount)) OVER (), 1) AS pct_of_revenue
FROM customer_shopping_behavior.customer
GROUP BY category
ORDER BY revenue DESC;
 Clothing and Accessories bring about 77% of revenue.

#13 [Key finding] Who gets subscriptions and discounts, by gender?
SELECT gender,
       COUNT(*) AS customers,
       ROUND(100 * SUM(CASE WHEN subscription_status = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 1) AS pct_subscribed,
       ROUND(100 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 1) AS pct_discounted
FROM customer_shopping_behavior.customer
GROUP BY gender;

#15  Customer value tiers: share of customers vs share of revenue
WITH tiers AS (
    SELECT purchase_amount,
           CASE WHEN purchase_amount <= 40 THEN '1. Low (up to $40)'
                WHEN purchase_amount <= 70 THEN '2. Mid ($41-70)'
                ELSE '3. High (above $70)' END AS spend_tier
                FROM customer_shopping_behavior.customer
)
SELECT spend_tier,
       COUNT(*) AS customers,
       ROUND(100 * COUNT(*) / SUM(COUNT(*)) OVER (), 1) AS pct_of_customers,
       ROUND(100 * SUM(purchase_amount) / SUM(SUM(purchase_amount)) OVER (), 1) AS pct_of_revenue
FROM tiers
GROUP BY spend_tier
ORDER BY spend_tier;

#16 Top 10 states by revenue
SELECT RANK() OVER (ORDER BY SUM(purchase_amount) DESC) AS state_rank,
       location,
       SUM(purchase_amount) AS revenue
FROM customer_shopping_behavior.customer
GROUP BY location
ORDER BY state_rank
LIMIT 10;

#17 Average spend by season
SELECT season,
       COUNT(*)                       AS purchases,
       ROUND(AVG(purchase_amount), 2) AS avg_spend
FROM customer_shopping_behavior.customer
GROUP BY season
ORDER BY avg_spend DESC; 
                
#18 Which categories rely most on discounts?
SELECT category,
       ROUND(100 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 1) AS discount_rate_pct,
       ROUND(AVG(purchase_amount), 2) AS avg_spend
FROM customer_shopping_behavior.customer
GROUP BY category
ORDER BY discount_rate_pct DESC;

#19 A saved query that feeds the Power BI KPI cards
CREATE OR REPLACE VIEW vw_kpi_summary AS
SELECT COUNT(*)                                                     AS customers,
       SUM(purchase_amount)                                         AS total_revenue,
       ROUND(AVG(purchase_amount), 2)                               AS avg_purchase,
       ROUND(AVG(review_rating), 2)                                 AS avg_rating,
       ROUND(100 * SUM(CASE WHEN subscription_status = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 1) AS subscriber_pct,
       ROUND(100 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 1)   AS discounted_pct
FROM customer_shopping_behavior.customer;
SELECT * FROM vw_kpi_summary;
